# Basic Auth 사용 (email:api_token을 base64 인코딩)
curl -X GET \
  'https://your-domain.atlassian.net/rest/api/3/search?jql=project=PROJ+AND+status!=Done' \
  -H 'Authorization: Basic <base64_credentials>' \
  -H 'Content-Type: application/json'

